def test_basic():
    pts = [[0.0, 0.0], [10.0, 10.0]]
    cents = [[0.0, 0.0], [10.0, 10.0]]
    assert solution.assign_clusters(pts, cents) == [0, 1]

def test_nearest_wins():
    pts = [[1.0, 1.0], [4.0, 4.0]]
    cents = [[0.0, 0.0], [5.0, 5.0]]
    assert solution.assign_clusters(pts, cents) == [0, 1]

def test_empty_centroids():
    try:
        solution.assign_clusters([[1.0]], [])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_tie_goes_low():
    assert solution.assign_clusters([[1.0, 1.0]], [[0.0, 0.0], [2.0, 2.0]]) == [0]

def test_single_centroid():
    assert solution.assign_clusters([[3.0], [-1.0]], [[0.0]]) == [0, 0]

def test_empty_points():
    assert solution.assign_clusters([], [[0.0, 0.0]]) == []

def test_no_mutation():
    pts = [[1.0, 2.0], [3.0, 4.0]]
    cents = [[0.0, 0.0], [5.0, 5.0]]
    solution.assign_clusters(pts, cents)
    assert pts == [[1.0, 2.0], [3.0, 4.0]]

def test_manhattan_differs():
    # L1 distances both equal 2 here; squared Euclidean prefers index 1.
    assert solution.assign_clusters([[2.0, 0.0]], [[0.0, 0.0], [1.0, 1.0]]) == [1]
